/// <summary>
/// Post run CBNF019_Observability_SalesOrderConfirmation Information event
/// </summary>
public void run()
{
    next run();

    CustConfirmJour confirmJournal;

    if (outputContract && outputContract.parmJournal() != null &&
        outputContract.parmJournal().tableId == tableName2Id(tableStr(CustConfirmJour)))
    {
        confirmJournal = outputContract.parmJournal();

        if (confirmJournal.SalesId != '' && confirmJournal.ConfirmDocNum != '')
        {
            METTelemetrySOConfirmationInfoEvent confirmationInfoEvent = METTelemetrySOConfirmationInfoEvent::construct();

            confirmationInfoEvent.addRunTimePropertyToAppinsights(confirmJournal);

            confirmationInfoEvent.processEvent(METTelemetryEventNames::SOConfirmedEvent);
        }
    }  
}

/// <summary>
/// Handles any errors that are thrown during the posting.
/// </summary>
/// <param name="_logText">
/// An error message.
/// </param>
/// <param name="_formletterParmTable">
/// A <c>FormletterParmTable</c> record.
/// </param>
protected void handleError(
    LogText             _logText,
    FormletterParmTable _formletterParmTable)
{
    next handleError(_logText, _formletterParmTable);

    if (_formletterParmTable.TableId == tableNum(SalesParmTable) &&
        documentStatus == DocumentStatus::Confirmation && formLetterContract != null && 
        formLetterContract.parmSourceTable().TableId == tableNum(SalesTable))
    {
        salesTable SalesTableTel = formLetterContract.parmSourceTable() as SalesTable;

        if (SalesTableTel.SalesId != '')
        {
            METTelemetrySOConfirmationErrorEvent::runTelemetryEvent(SalesTableTel.SalesId, _logText);
        }
    }
}
